#!/usr/bin/env bash
set -euo pipefail

openbaospace="openbao"
kubectl="sudo microk8s kubectl"

if [ -z "${OPENBAO_ROOT_TOKEN:-}" ]; then
  echo "Error: OPENBAO_ROOT_TOKEN must be set" >&2
  exit 1
fi

if ! ${kubectl} -n "${openbaospace}" get pod openbao-0 >/dev/null 2>&1; then
  echo "Error: OpenBao pod openbao-0 not found in namespace ${openbaospace}" >&2
  exit 1
fi

# Login
roottoken="${OPENBAO_ROOT_TOKEN}"
echo "${roottoken}" | ${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao login -

echo "Creating policy for secretspace eso-test..."
cat <<EOF | ${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao policy write eso-test -
# SPDX-License-Identifier: MPL-2.0
# Source and License see: https://github.com/Alfred-Sabitzer/microk8s-ubuntu/tree/main/applications/keepassxc
# Created on 2026-07-17 15:41:52
path "secret/data/eso-test/*" {
  capabilities = ["read"]
}
EOF

echo "Configuring role for secretspace eso-test..."
${kubectl} --namespace=${openbaospace} exec openbao-0 -- bao write auth/kubernetes/role/eso-test-role \
    bound_service_account_names=eso-test-sa \
    bound_service_account_namespaces=eso-test \
    audience="https://kubernetes.default.svc" \
    policies=eso-test \
    ttl=20m

echo "Activating secrets engine and creating secret for secretspace eso-test"
${kubectl} --namespace=${openbaospace} exec -i openbao-0 -- bao kv delete -mount=secret eso-test || true
echo "Create secret for secretspace eso-test"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/ob-basicauth || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/ob-basicauth  username="$(echo 'YWxmcmVk' | base64 --decode)" password="$(echo 'VnZGa1pHOHZvN3B6b1NDZkNoN0haVmJvV2xWcm5XSkQ=' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/ob-docker || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/ob-docker  .dockerconfigjson="$(echo 'eyJhdXRocyI6IHsiZG9ja2VyLmNvbSI6IHsidXNlcm5hbWUiOiAiZG9ja2VyIiwgInBhc3N3b3JkIjogIlp0UmJYYTR6dnFyT243OFlVVk1VVEpMeDdXMERDSU9PIiwgImVtYWlsIjogImRvY2tlckBzbGFpbnRlLmF0IiwgImF1dGgiOiAiWkc5amEyVnlPbHAwVW1KWVlUUjZkbkZ5VDI0M09GbFZWazFWVkVwTWVEZFhNRVJEU1U5UCJ9fX0=' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/ob-k8ssecret || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/ob-k8ssecret  username="$(echo 'YWxmcmVk' | base64 --decode)" password="$(echo 'VnZGa1pHOHZvN3B6b1NDZkNoN0haVmJvV2xWcm5XSkQ=' | base64 --decode)" url="$(echo 'aHR0cHM6Ly9zbGFpbnRlLmF0' | base64 --decode)" notes="$(echo 'VGVzdCBmb3Igc3RhbmRhcmQgSzhzLXNlY3JldA==' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/ob-k8ssimple || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/ob-k8ssimple  username="$(echo 'YWxmcmVk' | base64 --decode)" password="$(echo 'VnZGa1pHOHZvN3B6b1NDZkNoN0haVmJvV2xWcm5XSkQ=' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/ob-ssh || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/ob-ssh  ssh-publickey="$(echo 'c3NoLWVkMjU1MTkgQUFBQUMzTnphQzFsWkRJMU5URTVBQUFBSUkyZzkvUnR4V2wvK3VrK05la0s1VEZFUXc1UmRZZTVkeHFuZnU0SEEwWUsgYWxmcmVkQGFsZnJlZC1WaXJ0dWFsQm94' | base64 --decode)" ssh-privatekey="$(echo '' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/ob-tls || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/ob-tls  tls.crt="$(echo '' | base64 --decode)" tls.key="$(echo '' | base64 --decode)" ca.crt="$(echo '' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/obsync-k8ssecret || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/obsync-k8ssecret  username="$(echo 'YWxmcmVk' | base64 --decode)" password="$(echo 'VnZGa1pHOHZvN3B6b1NDZkNoN0haVmJvV2xWcm5XSkQ=' | base64 --decode)" url="$(echo 'aHR0cHM6Ly9zbGFpbnRlLmF0' | base64 --decode)" notes="$(echo 'VGVzdCBmb3Igc3RhbmRhcmQgSzhzLXNlY3JldA==' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/external-k8ssecret || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/external-k8ssecret  username="$(echo 'ZXh0ZXJuYWw=' | base64 --decode)" password="$(echo 'VU55YTU3NHVzWWF0VzlzclEzblhvelhMVFdNWWNGeDI5Q3lnM2taOQ==' | base64 --decode)" url="$(echo 'aHR0cHM6Ly9zbGFpbnRlLmF0' | base64 --decode)" notes="$(echo 'VGVzdCBmb3Igc3RhbmRhcmQgZXh0ZXJuYWwtazhzc2VjcmV0' | base64 --decode)"
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv delete secret/eso-test/external-another-secret || true
${kubectl} --namespace="${openbaospace}" exec -i openbao-0 -- bao kv put secret/eso-test/external-another-secret  username="$(echo 'bXlVc2VyTmFtZQ==' | base64 --decode)" password="$(echo 'eEVVcmUldnNqJmYkcyNuMmBNJjVVenVNaXR5NWViWGtGJn5ZMnR+Zg==' | base64 --decode)" url="$(echo 'aHR0cHM6Ly90aGlzLWlzLW15LWV4dGVybmFsLXNlY3JldC5hdA==' | base64 --decode)" notes="$(echo 'VGVzdCBmb3IgYW4gYWRkaXRpb25hbCBleHRlcm5hbCBzZWNyZXQ=' | base64 --decode)"
